def full(name):
    return ("يتضمن المنتج جميع القطع غير المطبوعة بطابعة 3D اللازمة لتجميع %s يعمل بالكامل. ولإكمال العمل، تحتاج أيضًا إلى تنزيل ملفات النموذج وطباعة القطع المتبقية بطابعة 3D." % name,
            "ئەم بەرهەمە هەموو ئەو پارچانەی تێدایە کە بە 3D چاپ ناکرێن و بۆ پێکەوەنانی %s بە شێوەیەکی تەواو کارا پێویستن. بۆ تەواوکردنی کارەکە، هەروەها پێویستە فایلەکانی مۆدێل دابگریت و پارچە ماوەکان بە 3D چاپ بکەیت." % name)
def visit(a, b, the=True):
    return ("لتنزيل ملفات نموذج %s والحصول على معلومات مفصّلة، يرجى زيارة صفحة %s على MakerWorld." % (a,b),
            "بۆ داگرتنی فایلەکانی مۆدێلی %s و وەرگرتنی زانیاریی ورد، تکایە سەردانی %s لە MakerWorld بکە." % (a,b))
